import { escURL, escHTML } from "./xss.js";
export function renderSquizLink(data, innerHTML = "") {
    const ext = extendSquizLink(data);
    return `<a ${ext.attrs}>${innerHTML || escHTML(data.label)}</a>`;
}
export function extendSquizLink(data) {
    const extended = {
        ...data,
        url: escURL(data.url),
        rel: data.target === "_blank" && !data.assetId ? "noopener noreferrer" : "",
        get attrs() {
            const { url: href, title, label, target, rel } = this;
            const parts = [`href=${href}`];
            if (title && title !== label)
                parts.push(`title=${title}`);
            if (target)
                parts.push(`target=${target}`);
            if (rel)
                parts.push(`rel=${rel}`);
            return parts.join(' ');
        }
    };
    return extended;
}
