import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { renderSquizLink, extendSquizLink } from "@ntgovernment/squiz-factory/utils/squiz-links";
import { componentAttrs, mergeDefaultModifiers } from "../_utils/component.helper";
import { detectBrand } from "../_utils/detectBrand";

const NTG_HOME_URL = "https://nt.gov.au";
const NTG_LOGO_URL = "https://nt.gov.au/_design/css/main.css/logo-ntg-mono.svg";
const COPYRIGHT_OWNER = "Northern Territory Government of Australia";
const DEFAULT_FINAL_TEXT =
  "The Northern Territory Government acknowledges the Traditional Owners of the Northern Territory and recognises their continuing cultural and spiritual connections to the lands, waters and communities. We pay our respects to all Aboriginal and Torres Strait Islander people and their cultures, their Elders past and present, and to future generations.";

export default {
  async main(input = {}) {
    const { menus = [], ancillary = [], finalText = "" } = input;

    return /* html */ `
    <footer ${componentAttrs("footer", mergeDefaultModifiers(input, ['fullwidth background']))} role="contentinfo">
        ${renderTop(menus)}
        ${renderMiddle(ancillary)}
        ${renderBottom(finalText)}
    </footer>`;
  },
};

function renderTop(menus) {
  const groups = (Array.isArray(menus) ? menus : [])
    .map((menu, index) => renderMenuGroup(menu, index))
    .filter(Boolean)
    .join("");

  if (!groups) return "";

  return `
    <div class="footer__top">
      <div class="footer__groups">
${groups}
      </div>
    </div>`;
}

function renderMiddle(ancillary) {
  const links = (Array.isArray(ancillary) ? ancillary : [])
    .map(renderAncillaryLink)
    .filter(Boolean)
    .join("");

  return `
    <div class="footer__middle">
      <div class="footer__brand">
        <a class="logo__ntg-primary" href="${escURL(NTG_HOME_URL)}" title="Visit NT.GOV.AU">
          <span class="sr-only">Visit NT.GOV.AU</span>
        </a>
      </div>
      ${links ? `<nav class="footer__ancillary" aria-label="Footer links"><ul class="footer__ancillary-list">${links}</ul></nav>` : ""}
    </div>`;
}

function renderBottom(finalText) {
  const year = new Date().getFullYear();
  const text = String(finalText ?? "").trim() || DEFAULT_FINAL_TEXT;

  return `
    <div class="footer__bottom">
      <div>${escHTML(text)}</div>
      <div>&copy; ${year} ${escHTML(COPYRIGHT_OWNER)}</div>
    </div>`;
}

function renderMenuGroup(menu, index) {
  if (!menu || typeof menu !== "object") return "";

  const title = String(menu.menuTitle ?? "").trim();
  const menuType = ["bullet", "icon", "none"].includes(menu.menuType)
    ? menu.menuType
    : "bullet";
  const items = Array.isArray(menu.menuItems) ? menu.menuItems : [];
  const renderedItems = items.map((item) => renderMenuItem(item, menuType)).filter(Boolean).join("");

  if (!title && !renderedItems) return "";

  const listModifier = menuType == 'bullet' ? '' : ' unstyled-list';
  return `
        <section class="footer__group footer__group--${escHTML(menuType)}" aria-labelledby="footer-group-${index}">
          ${title ? `<h2 id="footer-group-${index}">${escHTML(title)}</h2>` : ""}
          ${renderedItems ? `<ul class="footer__menu${listModifier}">${renderedItems}</ul>` : ""}
        </section>`;
}

function renderAncillaryLink(item) {
  const link = normalizeLink(item);
  if (!link) return "";
  return `<li>${renderLink(link, "none")}</li>`;
}

function renderMenuItem(item, menuType) {
  const linkNormalized = normalizeLink(item);
  if (linkNormalized) {
    return `<li>${renderLink(linkNormalized, menuType)}<!-- ${JSON.stringify({item, linkNormalized}, null, 2)} --></li>`;
  }

  const richText = normalizeFormattedText(item);
  if (!richText) return "";

  return `<li>${richText}<!-- ${JSON.stringify({item, linkNormalized}, null, 2)} --></li>`;
}

function renderLink(link, menuType) {
  const { label, attrs} = extendSquizLink(link);
  const showIcon = menuType === "icon";
  let contentHTML = escHTML(label);
  if (showIcon) {
    const { iconClass } = detectBrand(link);
    contentHTML = renderIcon(iconClass, label)
  };
  return `<a ${attrs} class="plain"><span class="decorate">${contentHTML}</span></a>`;
}

function renderIcon(iconClass, text) {
  return `<span class="footer__icon" aria-hidden="true"><i class="${escHTML(iconClass)}"></i></span><span>${escHTML(text)}</span>`;
}

function normalizeLink(item) {
  if (!item) return null;

  if (typeof item === "string") {
    return {
      url: item,
      title: item,
      target: "",
      rel: "",
      icon: "",
    };
  }

  const source = Object.prototype.hasOwnProperty.call(item, "link")
    ? item.link
    : item;

  if (typeof source === "string") {
    return {
      url: source,
      title: source,
      target: "",
      rel: "",
      icon: item.icon || "",
    };
  }

  if (!source || typeof source !== "object") return null;

  const url =
    source.url ||
    source.href ||
    source.asset_url ||
    source.assetUrl ||
    source.linkUrl ||
    "";
  const title =
    source.title ||
    source.name ||
    source.label ||
    source.text ||
    source.linkText ||
    source.asset_name ||
    source.assetName ||
    url;
  const target = source.target || (source.newWindow ? "_blank" : "");
  const rel = source.rel || (target === "_blank" ? "noopener noreferrer" : "");

  const link = {
    url,
    title,
    label: title,
    target,
    rel,
    icon: source.icon || "",
  };

  return url ? link : null;
}

function normalizeFormattedText(item) {
  if (typeof item === "string") return item;
  if (!item || typeof item !== "object") return "";

  const nested =
    item.link && typeof item.link === "object" && !Array.isArray(item.link)
      ? item.link
      : null;

  return (
    nested?.freeform ||
    nested?.html ||
    nested?.value ||
    nested?.body ||
    nested?.content ||
    nested?.text ||
    item.freeform ||
    item.html ||
    item.value ||
    item.body ||
    item.content ||
    item.text ||
    ""
  );
}
