const DETECTABLE_BRANDS = [
  {
    match: /facebook/i,
    iconClass: "fab fa-facebook-square",
  },
  {
    match: /linkedin/i,
    iconClass: "fab fa-linkedin",
  },
  {
    match: /youtube|youtu\.be/i,
    iconClass: "fab fa-youtube-square",
  },
  {
    match: /instagram/i,
    iconClass: "fab fa-instagram",
  },
  {
    match: /have\s*your\s*say|consult|engage|comment/i,
    iconClass: "fal fa-comment",
  },
  {
    match: /x\.com|twitter/i,
    iconClass: "fab fa-x-twitter",
  },
];

const DEFAULT_ICON = { iconClass: 'fa-light fa-arrow-up-right-from-square'}

export function detectBrand(link) {
  const haystack = [link.url, link.title, link.label].filter(Boolean).join(" ");
  return DETECTABLE_BRANDS.find((brand) => brand.match.test(haystack)) || DEFAULT_ICON;
}